CREATE TABLE security_settings(company_id TEXT PRIMARY KEY REFERENCES companies(id),rotation_days INTEGER NOT NULL DEFAULT 90 CHECK(rotation_days BETWEEN 1 AND 365),lockdown INTEGER NOT NULL DEFAULT 0 CHECK(lockdown IN(0,1)),version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE security_events(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),actor_id TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,result TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH','CRITICAL')),source TEXT NOT NULL,correlation_id TEXT NOT NULL,metadata TEXT NOT NULL CHECK(json_valid(metadata)),created_at TEXT NOT NULL,PRIMARY KEY(company_id,id));
CREATE TRIGGER security_events_no_update BEFORE UPDATE ON security_events BEGIN SELECT RAISE(ABORT,'Security evidence is append-only'); END;
CREATE TRIGGER security_events_no_delete BEFORE DELETE ON security_events BEGIN SELECT RAISE(ABORT,'Security evidence is retained'); END;
CREATE INDEX security_event_time ON security_events(company_id,created_at);
CREATE TABLE security_permissions(company_id TEXT NOT NULL,agent_id TEXT NOT NULL,resource_id TEXT NOT NULL,action TEXT NOT NULL CHECK(action IN('metadata.read','authenticate')),environment TEXT NOT NULL CHECK(environment IN('DEVELOPMENT','TESTING','STAGING','PRODUCTION')),expires_at INTEGER NOT NULL,granted_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(company_id,agent_id,resource_id,action,environment),FOREIGN KEY(company_id,agent_id) REFERENCES agents(company_id,id));
CREATE TABLE security_approvals(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),body TEXT NOT NULL CHECK(json_valid(body)),content_hash TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL,consumed_at TEXT,created_at TEXT NOT NULL,PRIMARY KEY(company_id,id));
CREATE TRIGGER security_approval_immutable BEFORE UPDATE OF id,company_id,body,content_hash,created_by,expires_at,created_at ON security_approvals BEGIN SELECT RAISE(ABORT,'Immutable security approval'); END;
CREATE TABLE security_reauth(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at INTEGER NOT NULL);
CREATE TABLE security_incidents(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),severity TEXT NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH','CRITICAL')),status TEXT NOT NULL CHECK(status IN('DETECTED','TRIAGED','CONTAINED','REMEDIATED','RECOVERED','CLOSED')),category TEXT NOT NULL,credential_id TEXT,evidence_id TEXT NOT NULL,confidence TEXT NOT NULL CHECK(confidence IN('LOW','MEDIUM','HIGH','CONFIRMED')),resolution TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(company_id,id));
CREATE TABLE security_alerts(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),dedupe_key TEXT NOT NULL,category TEXT NOT NULL,severity TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('OPEN','ACKNOWLEDGED')),created_at TEXT NOT NULL,PRIMARY KEY(company_id,id),UNIQUE(company_id,dedupe_key));
CREATE TABLE security_reports(id TEXT NOT NULL,company_id TEXT NOT NULL REFERENCES companies(id),kind TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),created_at TEXT NOT NULL,PRIMARY KEY(company_id,id));
CREATE TRIGGER security_reports_immutable BEFORE UPDATE ON security_reports BEGIN SELECT RAISE(ABORT,'Security reports immutable'); END;
